def _hasagg(e):
    return e[0] == "call" and e[1] in AGGS or any(_hasagg(x) for x in _children(e))
def _children(e):
    if e[0] in ("bin","cmp"): return [e[2],e[3]]
    if e[0] == "un": return [e[2]]
    if e[0] == "call" and e[2] != "*": return e[2]
    if e[0] == "nulltest": return [e[1]]
    if e[0] == "listtest": return [e[1]]+e[3]
    if e[0] == "between": return [e[1],e[3],e[4]]
    if e[0] == "like": return [e[1],e[3]]
