def _truth(v): return v is True
def _compare(a,b):
    if a is None or b is None: return None
    if type(a) in (int,float) and type(b) in (int,float): pass
    elif type(a) is type(b) and type(a) in (str,bool): pass
    else: raise QueryError("incompatible values in comparison")
    return (a>b)-(a<b)

